style.css:
@-moz-document domain("scratch.mit.edu") {
/* Global pastel rainbow background */
  body, html {
    background: linear-gradient(45deg, #FFB3BA, #FFDFBA, #FFFFBA, #BAFFC9, #BAE1FF);
    background-size: 400% 400%;
    animation: rainbowShift 15s ease infinite;
    color: #333; /* makes text readable */
    transition: background 1s ease;
  }

  @keyframes rainbowShift {
    0% {background-position: 0% 50%;}
    50% {background-position: 100% 50%;}
    100% {background-position: 0% 50%;}
  }

  /* Optional: pastel text shadows for all text */
  * {
    text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.6);
  }
}
